import requests
q='(breast cancer[Title/Abstract]) AND (neighborhood[Title/Abstract] OR neighbourhood[Title/Abstract] OR built environment[Title/Abstract]) AND (physical activity[Title/Abstract] OR recreational[Title/Abstract] OR leisure-time[Title/Abstract]) AND (survival[Title/Abstract] OR mortality[Title/Abstract])'
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmode':'json','retmax':20},timeout=20)
ids=r.json()['esearchresult']['idlist']
print('PMIDs:',ids)
if ids:
 x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
 for i in ids:
  z=x[i]; print(i,z.get('pubdate'),z.get('title'),z.get('fulljournalname'))
else: print('No exact keyword matches')
